<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">COACH</span><h1 class="fw-bold">Modération des avis</h1></div><a href="/coach" class="btn btn-outline-dark">Dashboard</a></div><div class="row g-3"><?php foreach($items as $x): ?><div class="col-md-6"><div class="form-card h-100"><div class="d-flex justify-content-between"><strong><?=e($x['title'])?></strong><span class="badge text-bg-light"><?=e($x['status'])?></span></div><div class="stars my-2"><?=str_repeat('★',(int)$x['rating'])?></div><p><?=e($x['comment'])?></p><small><?=e($x['firstname'].' '.$x['lastname'])?></small><?php if($x['status']==='pending'): ?><div class="d-flex gap-2 mt-3"><?php foreach(['approved'=>'Valider','rejected'=>'Refuser'] as $v=>$label): ?><form method="post" action="/coach/avis/status"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="status" value="<?=$v?>"><button class="btn btn-sm <?=$v==='approved'?'btn-success':'btn-outline-danger'?>"><?=$label?></button></form><?php endforeach; ?></div><?php endif; ?></div></div><?php endforeach; ?></div></main>